import {Chess} from './vendor/chess.js';
export function parseGame(raw,username){if(raw.rules&&raw.rules!=='chess')return null;const c=new Chess();c.loadPgn(raw.pgn);const h=c.getHeaders();const white=raw.white?.username||h.White,black=raw.black?.username||h.Black;const color=white?.toLowerCase()===username.toLowerCase()?'w':black?.toLowerCase()===username.toLowerCase()?'b':null;if(!color)return null;const outcome=h.Result==='1/2-1/2'?'draw':h.Result==='1-0'?(color==='w'?'win':'loss'):h.Result==='0-1'?(color==='b'?'win':'loss'):null;if(!outcome)return null;const history=c.history({verbose:true});return {color,outcome,speed:raw.time_class||'unknown',moves:history.map(m=>m.from+m.to+(m.promotion||'')),sans:history.map(m=>m.san),initial:h.FEN||new Chess().fen(),url:raw.url||'',end:raw.end_time||0};}
export function summarize(games,path,color,speed,horizon=0){const matches=games.filter(g=>g.color===color&&(speed==='all'||g.speed===speed)&&path.every((m,i)=>g.moves[i]===m));const continuing=matches.filter(g=>g.moves.length>path.length),map=new Map();for(const g of continuing){const i=path.length,key=g.moves[i];if(!map.has(key))map.set(key,{uci:key,san:g.sans[i],n:0,win:0,draw:0,loss:0,paths:new Set()});const r=map.get(key);r.n++;r[g.outcome]++;r.paths.add(g.moves.slice(i+1,horizon?i+1+horizon:undefined).join(' '));}return {matched:matches.length,ended:matches.length-continuing.length,total:continuing.length,rows:[...map.values()].map(r=>({...r,paths:undefined,branches:r.paths.size,frequency:r.n/continuing.length,winrate:r.win/r.n}))};}
